#include <cstddef>
#include <cstdint>
#include <utility>
#include <vector>

template <typename T>
class ComponentStore
{
public:
    explicit ComponentStore(std::size_t maxEntities) : m_sparse(maxEntities, kNone) {}

    void add(std::uint32_t entity, const T& component)
    {
        if (entity >= m_sparse.size()) return;
        if (m_sparse[entity] != kNone) { m_components[m_sparse[entity]] = component; return; }
        m_sparse[entity] = static_cast<std::uint32_t>(m_dense.size());
        m_dense.push_back(entity);
        m_components.push_back(component);
    }

    bool has(std::uint32_t entity) const { return entity < m_sparse.size() && m_sparse[entity] != kNone; }

    T* get(std::uint32_t entity) { return has(entity) ? &m_components[m_sparse[entity]] : nullptr; }

    bool remove(std::uint32_t entity)
    {
        if (!has(entity)) return false;
        const std::uint32_t index{ m_sparse[entity] };
        const std::uint32_t last{ static_cast<std::uint32_t>(m_dense.size() - 1) };
        if (index != last)
        {
            // Move the last component into the hole and tell its entity where it went.
            m_components[index] = std::move(m_components[last]);
            m_dense[index] = m_dense[last];
            m_sparse[m_dense[index]] = index;
        }
        m_components.pop_back();
        m_dense.pop_back();
        m_sparse[entity] = kNone;
        return true;
    }

    std::size_t size() const { return m_dense.size(); }
    const std::vector<std::uint32_t>& entities() const { return m_dense; }
    const std::vector<T>& components() const { return m_components; }

private:
    static constexpr std::uint32_t kNone{ 0xFFFFFFFFu };
    std::vector<std::uint32_t> m_sparse;      // entity -> index in the dense arrays
    std::vector<std::uint32_t> m_dense;       // index -> entity
    std::vector<T> m_components;              // index -> component
};

unitTests:
struct Position { float x, y; };
TEST("add and get") { ComponentStore<Position> s{ 10 }; s.add(3, { 1, 2 }); CHECK(s.has(3)); CHECK(!s.has(4)); CHECK_NEAR(s.get(3)->y, 2.0, 1e-9); CHECK(s.get(4) == nullptr); }
TEST("adding again replaces") { ComponentStore<int> s{ 10 }; s.add(1, 5); s.add(1, 9); CHECK_EQ(*s.get(1), 9); CHECK_EQ(s.size(), std::size_t{ 1 }); }
TEST("dense arrays stay in step")
{
    ComponentStore<int> s{ 10 };
    s.add(1, 10); s.add(4, 40); s.add(3, 30);
    CHECK(s.entities() == std::vector<std::uint32_t>({ 1, 4, 3 }));
    CHECK(s.components() == std::vector<int>({ 10, 40, 30 }));
}
TEST("remove from the middle moves the last one in")
{
    ComponentStore<int> s{ 10 };
    s.add(1, 10); s.add(4, 40); s.add(3, 30);
    CHECK(s.remove(1));
    CHECK(!s.has(1));
    CHECK(s.entities() == std::vector<std::uint32_t>({ 3, 4 }));
    CHECK_EQ(*s.get(3), 30);
    CHECK_EQ(*s.get(4), 40);
}
TEST("remove the last one") { ComponentStore<int> s{ 5 }; s.add(0, 1); s.add(2, 3); CHECK(s.remove(2)); CHECK_EQ(s.size(), std::size_t{ 1 }); CHECK_EQ(*s.get(0), 1); }
TEST("remove twice") { ComponentStore<int> s{ 5 }; s.add(0, 1); CHECK(s.remove(0)); CHECK(!s.remove(0)); CHECK_EQ(s.size(), std::size_t{ 0 }); }
TEST("out of range ids") { ComponentStore<int> s{ 4 }; s.add(99, 1); CHECK(!s.has(99)); CHECK(s.get(99) == nullptr); CHECK(!s.remove(99)); CHECK_EQ(s.size(), std::size_t{ 0 }); }
TEST("re-adding after removal") { ComponentStore<int> s{ 4 }; s.add(2, 7); s.remove(2); s.add(2, 8); CHECK_EQ(*s.get(2), 8); }

